begin
 select jsonb_agg(jsonb_build_object('release_id',release_id,'sha256',sha256,'supported',supported,'approved_for_new',approved_for_new,'successor',successor,'upgrade_policy',upgrade_policy,'compatibility',compatibility) order by release_id) from platform_private.approved_shop_releases into actual;
 -- Admit only the exact known v8 baseline or the exact already-promoted v9 state.
 -- Unknown/missing historical releases, changed fingerprints/support/protocols,
 -- unexpected successors, partial v9 records and ambiguous fresh approvals fail closed.
 if actual is distinct from expected_before and actual is distinct from expected_after
 then raise exception 'Historical release fingerprint, support policy or approval state conflict; reconcile before support-v9 promotion';end if;
end $$;
insert into platform_private.approved_shop_releases
 (release_id,sha256,supported,approved_for_new,successor,upgrade_policy,compatibility)
