 select jsonb_agg(jsonb_build_object('release_id',release_id,'sha256',sha256,'supported',supported,'approved_for_new',approved_for_new,'successor',successor,'upgrade_policy',upgrade_policy,'compatibility',compatibility) order by release_id) from platform_private.approved_shop_releases into actual;
